from typing import Sequence, List

def allocate_cents(total: int, weights: Sequence[int]) -> List[int]:
    n = len(weights)
    if n == 0:
        return []
    if total == 0:
        return [0] * n
    if any(w < 0 for w in weights):
        raise ValueError("negative weight")
    s = sum(weights)
    if s == 0:
        if total != 0:
            raise ValueError("zero weights")
        return [0] * n
    base = [(total * w) // s for w in weights]
    rem = total - sum(base)
    fracs = [(total * w) / s - b for w, b in zip(weights, base)]
    if rem > 0:
        idx = sorted(range(n), key=lambda i: (-fracs[i], i))[:rem]
        for i in idx:
            base[i] += 1
    elif rem < 0:
        idx = sorted(range(n), key=lambda i: (fracs[i], i))[:-rem]
        for i in idx:
            base[i] -= 1
    return base
